def gen(rng):
    def fmt(iv):
        return '%d\n%s\n%s' % (len(iv), ' '.join(str(a) for a, d in iv), ' '.join(str(d) for a, d in iv))
    tests = [
        fmt([(7, 7)]),
        fmt([(1, 5), (5, 9)]),
        fmt([(1, 4), (5, 9)]),
        fmt([(3, 3), (3, 3), (3, 3)]),
        fmt([(10, 25), (20, 35), (30, 45), (25, 28), (40, 50)]),
        fmt([(0, 10**9), (5, 6), (7, 7)]),
    ]
    for n in (2, 3, 4, 6, 8, 12, 20, 30):
        for _ in range(2):
            iv = []
            for _ in range(n):
                a = rng.randint(0, 25)
                iv.append((a, a + rng.randint(0, 8)))
            tests.append(fmt(iv))
    def big(n, hi, maxlen):
        iv = []
        for _ in range(n):
            a = rng.randint(0, hi)
            iv.append((a, min(10**9, a + rng.randint(0, maxlen))))
        return iv
    tests.append(fmt(big(20000, 10**9, 10**7)))
    tests.append(fmt(big(100000, 10**9, 5 * 10**6)))
    tests.append(fmt([(i, 10**9 - i) for i in range(100000)]))
    iv = [(2 * i, 2 * i + 2) for i in range(100000)]
    tests.append(fmt(iv))
    return tests
